import{_ as n,o as t,c as r,a2 as a}from"./chunks/framework.Buc7gXeZ.js";const c=JSON.parse('{"title":"Felder konfigurieren","description":"Formularfelder beschriften, als Pflichtfeld setzen, vorbelegen und verbergen.","frontmatter":{"title":"Felder konfigurieren","description":"Formularfelder beschriften, als Pflichtfeld setzen, vorbelegen und verbergen."},"headers":[],"relativePath":"formulare/felder-konfigurieren.md","filePath":"formulare/felder-konfigurieren.md","lastUpdated":1786092153000}'),i={name:"formulare/felder-konfigurieren.md"};function l(d,e,s,o,h,u){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="felder-konfigurieren" tabindex="-1">Felder konfigurieren <a class="header-anchor" href="#felder-konfigurieren" aria-label="Permalink to &quot;Felder konfigurieren&quot;">​</a></h1><p>Jedes Feld eines Formulars lässt sich einzeln einstellen. Ein Klick auf <strong>Bearbeiten</strong> am Feld öffnet die <strong>Feldeinstellungen</strong>.</p><h2 id="beschriftung-und-hilfetext" tabindex="-1">Beschriftung und Hilfetext <a class="header-anchor" href="#beschriftung-und-hilfetext" aria-label="Permalink to &quot;Beschriftung und Hilfetext&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Label</strong></td><td>Beschriftung im Formular</td></tr><tr><td><strong>Beschreibung</strong></td><td>Erklärender Text unter der Beschriftung</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Das Label gilt nur für dieses Formular</p><p>Der Spaltenname im Grid bleibt unverändert. Sie können also intern <code>status_kunde</code> heißen lassen und im Formular <em>Wie zufrieden sind Sie?</em> fragen.</p><p>Nutzen Sie das: Interne Feldnamen sind für Ausfüllende oft unverständlich.</p></div><h2 id="pflichtfeld" tabindex="-1">Pflichtfeld <a class="header-anchor" href="#pflichtfeld" aria-label="Permalink to &quot;Pflichtfeld&quot;">​</a></h2><p><strong>Pflichtfeld</strong> verhindert das Absenden, solange das Feld leer ist. Die Meldung lautet <em>Bitte füllen Sie dieses Pflichtfeld aus.</em></p><div class="warning custom-block"><p class="custom-block-title">Sparsam einsetzen</p><p>Jedes Pflichtfeld erhöht die Abbruchquote. Fragen Sie sich bei jedem: Kann ich den Vorgang ohne diese Angabe wirklich nicht bearbeiten?</p><p>Bei mehrseitigen Formularen gehören Pflichtfelder nach vorn — bricht jemand ab, haben Sie wenigstens das Wichtigste.</p></div><h2 id="eingabeverhalten" tabindex="-1">Eingabeverhalten <a class="header-anchor" href="#eingabeverhalten" aria-label="Permalink to &quot;Eingabeverhalten&quot;">​</a></h2><h3 id="mehrzeilig" tabindex="-1">Mehrzeilig <a class="header-anchor" href="#mehrzeilig" aria-label="Permalink to &quot;Mehrzeilig&quot;">​</a></h3><p>Bei Textfeldern: mehrere Zeilen statt einer. Für Kommentare, Beschreibungen und Anmerkungen.</p><h3 id="komponententyp" tabindex="-1">Komponententyp <a class="header-anchor" href="#komponententyp" aria-label="Permalink to &quot;Komponententyp&quot;">​</a></h3><p>Bestimmt, wie das Feld dargestellt wird:</p><table tabindex="0"><thead><tr><th>Spaltentyp</th><th>Auswahl</th></tr></thead><tbody><tr><td>Einzelauswahl, Mehrfachauswahl</td><td><em>Dropdown-Menü</em> oder <em>Liste</em></td></tr><tr><td>Dateien</td><td><em>Datei auswählen</em> oder <em>Video aufnehmen</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Dropdown oder Liste?</p><p><strong>Liste</strong> zeigt alle Optionen sofort — gut bei bis zu etwa fünf Optionen und wenn die Auswahl bewusst getroffen werden soll.</p><p><strong>Dropdown-Menü</strong> spart Platz — besser bei vielen Optionen und auf Mobilgeräten.</p></div><h3 id="nur-hinzufugen-von-dateien-erlauben" tabindex="-1">Nur Hinzufügen von Dateien erlauben <a class="header-anchor" href="#nur-hinzufugen-von-dateien-erlauben" aria-label="Permalink to &quot;Nur Hinzufügen von Dateien erlauben&quot;">​</a></h3><p>Bei Dateifeldern: Ausfüllende können Anhänge ergänzen, aber bestehende nicht löschen.</p><div class="tip custom-block"><p class="custom-block-title">Wichtig bei Bearbeitungs-Formularen</p><p>Wenn ein Formular einen <strong>bestehenden</strong> Eintrag bearbeitet, verhindert diese Einstellung, dass bereits hochgeladene Dokumente versehentlich entfernt werden.</p></div><h3 id="barcode-scanner-aktivieren" tabindex="-1">Barcode-Scanner aktivieren <a class="header-anchor" href="#barcode-scanner-aktivieren" aria-label="Permalink to &quot;Barcode-Scanner aktivieren&quot;">​</a></h3><p>Erlaubt, das Feld per Kamera zu befüllen — für Artikelnummern, Seriennummern, Inventarkennzeichen.</p><h2 id="vorbelegen-und-verbergen" tabindex="-1">Vorbelegen und verbergen <a class="header-anchor" href="#vorbelegen-und-verbergen" aria-label="Permalink to &quot;Vorbelegen und verbergen&quot;">​</a></h2><p>Drei Einstellungen, die zusammen gedacht werden wollen:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Vorausgefüllt</strong></td><td>Ein Standardwert steht beim Öffnen bereits im Feld</td></tr><tr><td><strong>Nicht änderbar</strong></td><td>Das Feld wird angezeigt, lässt sich aber nicht bearbeiten</td></tr><tr><td><strong>Nicht sichtbar</strong></td><td>Das Feld wird nicht angezeigt, aber mitgeschickt</td></tr></tbody></table><h3 id="typische-kombinationen" tabindex="-1">Typische Kombinationen <a class="header-anchor" href="#typische-kombinationen" aria-label="Permalink to &quot;Typische Kombinationen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ziel</th><th>Einstellungen</th></tr></thead><tbody><tr><td>Herkunft mitschreiben, ohne dass es jemand sieht</td><td><em>Nicht sichtbar</em> + Wert über <a href="/docs/formulare/vorausgefuellte-links">vorausgefüllten Link</a></td></tr><tr><td>Kontext anzeigen, aber festhalten</td><td><em>Vorausgefüllt</em> + <em>Nicht änderbar</em></td></tr><tr><td>Vorschlag machen, Änderung erlauben</td><td>nur <em>Vorausgefüllt</em></td></tr><tr><td>Bestehende Daten zeigen, ohne Bearbeitung</td><td><em>Nicht änderbar</em></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">„Nicht sichtbar&quot; ist nicht vertraulich</p><p>Das Feld wird in der Oberfläche ausgeblendet — mehr nicht. Bei einem vorausgefüllten Link steht der Wert sogar in der Adresse und ist für jeden lesbar, der den Link hat.</p><p>Legen Sie dort keine personenbezogenen oder vertraulichen Daten hinein.</p></div><h2 id="tarifabhangige-einstellungen" tabindex="-1">Tarifabhängige Einstellungen <a class="header-anchor" href="#tarifabhangige-einstellungen" aria-label="Permalink to &quot;Tarifabhängige Einstellungen&quot;">​</a></h2><p>Vier Einstellungen sind nicht in allen Tarifen verfügbar:</p><ul><li><strong>Nicht änderbar</strong></li><li><strong>Nicht sichtbar</strong></li><li><strong>Vorausgefüllt</strong></li><li><strong>Barcode-Scanner aktivieren</strong></li></ul><div class="warning custom-block"><p class="custom-block-title">Bei einem Downgrade können Einstellungen entfallen</p><p>Wechselt der Space in einen niedrigeren Tarif, entfernt ApptiveGrid kostenpflichtige Formulareinstellungen. Prüfen Sie Ihre Formulare nach einem Tarifwechsel.</p></div><h2 id="feld-entfernen" tabindex="-1">Feld entfernen <a class="header-anchor" href="#feld-entfernen" aria-label="Permalink to &quot;Feld entfernen&quot;">​</a></h2><p>Über <strong>Entfernen</strong> in den Feldeinstellungen. Das nimmt das Feld aus dem <strong>Formular</strong> — die Spalte im Grid und ihre Daten bleiben unangetastet.</p><h2 id="welche-felder-nicht-abgefragt-werden-konnen" tabindex="-1">Welche Felder nicht abgefragt werden können <a class="header-anchor" href="#welche-felder-nicht-abgefragt-werden-konnen" aria-label="Permalink to &quot;Welche Felder nicht abgefragt werden können&quot;">​</a></h2><p>Vier Spaltentypen haben kein Formularfeld:</p><table tabindex="0"><thead><tr><th>Typ</th><th>Grund</th></tr></thead><tbody><tr><td><strong>Formatierter Text</strong></td><td>kein Eingabefeld hinterlegt</td></tr><tr><td><strong>Wert übernehmen</strong></td><td>berechnet</td></tr><tr><td><strong>Summe berechnen</strong></td><td>berechnet</td></tr><tr><td><strong>Formel</strong></td><td>berechnet</td></tr></tbody></table><p>Für längeren Text nehmen Sie stattdessen <strong>Text</strong> mit der Einstellung <em>Mehrzeilig</em>.</p><h2 id="validierung" tabindex="-1">Validierung <a class="header-anchor" href="#validierung" aria-label="Permalink to &quot;Validierung&quot;">​</a></h2><p>ApptiveGrid prüft Eingaben nach Spaltentyp. Die Meldungen stehen unter <a href="/docs/fehlerbehebung/haeufige-fehlermeldungen">Häufige Fehlermeldungen</a> — etwa <em>Es sind nur Zahlen (0-9) erlaubt</em> oder <em>Internationale Vorwahl ist erforderlich (z.B. +49)</em>.</p><div class="tip custom-block"><p class="custom-block-title">Erwartete Formate in der Beschreibung nennen</p><p>Bei Telefonnummern, Datumsangaben und Koordinaten sparen Sie sich Fehleingaben, wenn die Feldbeschreibung ein Beispiel enthält.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/formulare/formular-erstellen">Formular erstellen</a></li><li><a href="/docs/formulare/gestaltung">Gestaltung</a></li><li><a href="/docs/formulare/vorausgefuellte-links">Vorausgefüllte Links</a></li></ul>',41)])])}const b=n(i,[["render",l]]);export{c as __pageData,b as default};
